using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void music_dialog(Control o)
    {
        var dialog=window(o,"Procedural Music Composer",new Vector2I(800,720));var windowNode=dialog["window"].As<Window>();var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};dialog["host"].As<Node>().AddChild(scroll);var host=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(host);var settings=Dict(Document(o),"composer_settings").Duplicate(true);if(settings.Count==0)settings=new Settings{["style"]="Ambient",["mood"]="Calm",["tempo"]=Document(o).Get("tempo"),["key"]=Document(o).Get("key"),["scale"]=Document(o).Get("scale"),["duration"]=24.0,["energy"]=.5,["complexity"]=.4,["repetition"]=.7,["variation"]=.35,["seed"]=1};
        using var composer=new AudioComposerOperations();ChoiceAction(o,host,"Style",composer.styles(),Get(settings,"style","Ambient").AsString(),value=>settings["style"]=value);ChoiceAction(o,host,"Mood",new GArray{"Calm","Bright","Playful","Dark","Sad","Neutral"},Get(settings,"mood","Calm").AsString(),value=>settings["mood"]=value);var scales=new GArray();foreach(var key in composer.scales().Keys)scales.Add(key);ChoiceAction(o,host,"Scale",scales,Get(settings,"scale","minor").AsString(),value=>settings["scale"]=value);var keys=new GArray{"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"};ChoiceAction(o,host,"Key",keys,keys[Math.Clamp(Get(settings,"key",0).AsInt32(),0,11)].AsString(),value=>settings["key"]=keys.IndexOf(value));foreach(var info in new[]{("tempo",20.0,300.0,1.0),("duration",2.0,240.0,1.0),("energy",0.0,1.0,.01),("complexity",0.0,1.0,.01),("repetition",0.0,1.0,.01),("variation",0.0,1.0,.01),("seed",0.0,2147483647.0,1.0)}){string key=info.Item1;NumberAction(o,host,key.Capitalize(),Get(settings,key,1).AsDouble(),info.Item2,info.Item3,info.Item4,value=>settings[key]=value);}
        var extra=GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_composer_controls.gd").New().As<Control>();host.AddChild(extra);extra.Call("setup",settings,Document(o).Get("sections"));var roles=ChoiceAction(o,host,"Regenerate",new GArray{"Entire arrangement","melody","chords","bass","drums","pad"},"Entire arrangement",_=>{});var sections=new GArray{"All sections"};var sectionIds=new GArray{""};foreach(var raw in Items(Document(o),"sections")){var section=raw.AsGodotDictionary();sections.Add(section["name"]);sectionIds.Add(section["id"]);}var sectionChoice=ChoiceAction(o,host,"Section",sections,"All sections",_=>{});label(host,"Editable, rule-based musical sketches. Composer tempo is saved with its source patterns; existing project conductor points are preserved. Generation does not follow variable project tempo or meter. Acoustic-like patches are synthesis; use your own samples for recorded acoustic instruments.");ActionButton(dialog["host"].As<Node>(),"Generate editable music",()=>{string role=roles.Selected==0?"":roles.GetItemText(roles.Selected);string sectionId=sectionIds[sectionChoice.Selected].AsString();settings.Remove("section_layout");settings.Merge(extra.Call("settings_copy").AsGodotDictionary(),true);compose(o,settings,role,sectionId);windowNode.QueueFree();});
    }
    public void compose(Control o,Settings settings,string role,string sectionId)
    {
        using var composer=new AudioComposerControlOperations();var previous=composer.snapshot_arrangement(Document(o));var config=settings.Duplicate(true);var signature=Document(o).Get("time_signature").AsVector2I();config["time_signature"]=new GArray{signature.X,signature.Y};if(role.Length>0||sectionId.Length>0){config["tempo"]=Document(o).Call("arrangement_tempo");config["time_signature"]=Get(Dict(Document(o),"composer_settings"),"time_signature",config["time_signature"]);config["key"]=Document(o).Get("key");config["scale"]=Document(o).Get("scale");}Work(o,"composer",Session(o).Get("revision").AsInt64(),job=>{using var worker=new AudioComposerControlOperations();return worker.render_arrangement(config,previous,role,sectionId,job,44100);});
    }
    public string smart_track_problem(Control o,string trackId)
    {
        var track=Document(o).Call("track_for_id",trackId).AsGodotDictionary();if(track.Count==0)return "The target track is no longer available. No edits were applied.";if(Get(track,"locked",false).AsBool()||track.ContainsKey("frozen_track")||track.ContainsKey("frozen_source"))return "Unlock or unfreeze the target track before this edit. No edits were applied.";return _frameLanes.is_lane(track)?"Choose an audio or instrument track as the edit target.":"";
    }
    public void send_dialog(Control o)
    {
        var track=Document(o).Call("track_for_id",Session(o).Get("selected_track")).AsGodotDictionary();if(_frameLanes.is_lane(track)){notice(o,"Automation lanes do not carry audio sends. Select an audio or group track.");return;}if(track.Count==0)return;if(Get(track,"locked",false).AsBool()){notice(o,"Unlock this track to edit its sends.");return;}var dialog=window(o,"Post-fader sends",new Vector2I(540,420));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var labels=new GArray();var ids=new GArray();foreach(var raw in Items(Document(o),"tracks")){var other=raw.AsGodotDictionary();if(other["id"].AsString()!=track["id"].AsString()&&!_frameLanes.is_lane(other)){labels.Add(other["name"]);ids.Add(other["id"]);}}var sends=Get(track,"sends",new GArray()).AsGodotArray();for(int index=0;index<sends.Count;index++){int slot=index;var send=sends[index].AsGodotDictionary();var row=new HFlowContainer();host.AddChild(row);var destination=Document(o).Call("track_for_id",Get(send,"target","")).AsGodotDictionary();label(row,Get(destination,"name","Missing track").AsString());NumberAction(o,row,"dB",Get(send,"volume_db",-12).AsDouble(),-60,6,.1,value=>EditAction(o,"Adjust send",()=>send["volume_db"]=value));ActionButton(row,"Remove",()=>{SessionAction(o,"Remove send",()=>sends.RemoveAt(slot));windowNode.QueueFree();send_dialog(o);});}if(labels.Count>0){var choice=ChoiceAction(o,host,"Destination",labels,labels[0].AsString(),_=>{});double gain=-12;NumberAction(o,host,"Send (dB)",gain,-60,6,.1,value=>gain=value);ActionButton(host,"Add send",()=>{var proposed=Get(track,"sends",new GArray()).AsGodotArray().Duplicate(true);proposed.Add(new Settings{["target"]=ids[choice.Selected],["volume_db"]=gain});if(!Session(o).Call("set_track_value",track["id"],"sends",proposed).AsBool())notice(o,"Routing would create feedback.");windowNode.QueueFree();send_dialog(o);});}else label(host,"Add a group or destination track before creating a send.");label(host,"Post-fader sends are included in exact rendered preview and export. Native live monitoring uses the main output route.");
    }
}
